<rect x="-16" y="52" width="32" height="8" rx="2" fill="${fill}"/>
</g>`;
};
const cells = [];
for (let r = 0; r < 5; r++) for (let c = 0; c < 5; c++) {
const n = r * 5 + c;
cells.push(glass(214 + c * 158, 736 + r * 134, .82, n === 24 ? 'half' : 'full'));
}
const ticks = [];
